import org.junit.jupiter.api.Test;

class FastNQuadsParserReuseTest {

	@Test
	void startsANewDocumentAfterAMalformedFinalLine() throws Exception {
		FastNTriplesParser parser = new FastNTriplesParser(RDFFormat.NQUADS, () -> false);
		assertThrows(RDFParseException.class,
				() -> parser.parse(new ByteArrayInputStream("broken".getBytes(StandardCharsets.UTF_8)),
						(subject, predicate, object, context) -> {
						}));
		List<byte[]> subjects = new ArrayList<>();
		byte[] document = "<urn:reused:s> <urn:p> <urn:o> <urn:g> .".getBytes(StandardCharsets.UTF_8);
		assertEquals(1L, parser.parse(new ByteArrayInputStream(document),
				(subject, predicate, object, context) -> subjects.add(subject)));
		assertEquals(SimpleValueFactory.getInstance().createIRI("urn:reused:s"),
				CanonicalTermCodec.decode(subjects.getFirst()));
	}
}
